var mock = new Mock<IEmailService>();
var service = new OrderService(mock.Object);

service.ProcessOrder(new Order());

// Verify method was called
mock.Verify(x => x.Send(It.IsAny<string>()));

// Verify called specific number of times
mock.Verify(x => x.Send(It.IsAny<string>()), Times.Once);
mock.Verify(x => x.Send(It.IsAny<string>()), Times.Exactly(3));

// Verify with specific parameters
mock.Verify(x => x.Send("test@example.com"));

// Verify with condition
mock.Verify(x => x.Send(It.Is<string>(s => s.Contains("@"))));
